// mFAST decode benchmark, matching benchmarks/compare_test.go:
// per packet: reset dictionary, decode one message, read every MDEntryPx and
// MDEntrySize, checksum += price mantissa at exponent -2 * size (exact ints).
#include <mfast.h>
#include <mfast/coder/fast_decoder.h>
#include <mfast/coder/fast_decoder_v2.h>
#include <mfast/xml_parser/dynamic_templates_description.h>
#include "templates.h" // generated by fast_type_gen from the same XML

#include <algorithm>
#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <iterator>
#include <new>
#include <string>
#include <vector>

static const int64_t kWant = 9260955000;

// ---- allocation counting: global operator new + mFAST's own allocator ----
static uint64_t g_allocs = 0;
void *operator new(std::size_t n) {
  ++g_allocs;
  if (void *p = std::malloc(n ? n : 1)) return p;
  throw std::bad_alloc();
}
void operator delete(void *p) noexcept { std::free(p); }
void operator delete(void *p, std::size_t) noexcept { std::free(p); }

struct counting_allocator : mfast::malloc_allocator {
  void *allocate(std::size_t n) override { ++g_allocs; return malloc_allocator::allocate(n); }
  std::size_t reallocate(void *&p, std::size_t o, std::size_t n) override {
    ++g_allocs; return malloc_allocator::reallocate(p, o, n);
  }
};

static std::string slurp(const std::string &path) {
  std::ifstream f(path, std::ios::binary);
  if (!f) { std::fprintf(stderr, "cannot read %s\n", path.c_str()); std::exit(2); }
  return std::string(std::istreambuf_iterator<char>(f), {});
}

static int64_t at_exp_minus2(int64_t m, int exp) {
  for (; exp > -2; --exp) m *= 10;
  for (; exp < -2; ++exp) m /= 10;
  return m;
}

// Dynamic style: runtime XML, fields looked up by name every packet (like the
// Go harness's Sequence("MDEntries") / Get("MDEntryPx")).
static int64_t sum_dynamic(const mfast::message_cref &msg) {
  mfast::sequence_cref seq(msg[msg.field_index_with_name("MDEntries")]);
  int64_t sum = 0;
  for (auto e : seq) {
    mfast::field_cref px = e[e.field_index_with_name("MDEntryPx")];
    mfast::field_cref sz = e[e.field_index_with_name("MDEntrySize")];
    int64_t m = 0, s = 0;
    if (px.present()) {
      mfast::decimal_cref d(px);
      m = at_exp_minus2(d.mantissa(), d.exponent());
    }
    if (sz.present()) s = mfast::int64_cref(sz).value();
    sum += m * s;
  }
  return sum;
}

// Static style: generated accessors (fixed field indices, no name lookup).
static int64_t sum_static(const mfast::message_cref &msg) {
  templates::MDIncRefresh_cref ref(msg);
  int64_t sum = 0;
  for (auto e : ref.get_MDEntries()) {
    auto px = e.get_MDEntryPx();
    auto sz = e.get_MDEntrySize();
    int64_t m = px.present() ? at_exp_minus2(px.mantissa(), px.exponent()) : 0;
    int64_t s = sz.present() ? sz.value() : 0;
    sum += m * s;
  }
  return sum;
}

template <class Decode>
static void bench(const char *label, const std::string &pkt, Decode decode_once) {
  using clk = std::chrono::steady_clock;
  const char *b = pkt.data(), *e = b + pkt.size();

  int64_t first = decode_once(b, e);
  if (first != kWant) {
    std::fprintf(stderr, "%s: checksum %lld, want %lld\n", label, (long long)first, (long long)kWant);
    std::exit(1);
  }

  // Warm up ~1s and calibrate an iteration count giving ~2s per run.
  uint64_t n = 0;
  int64_t acc = 0;
  auto t0 = clk::now();
  while (clk::now() - t0 < std::chrono::seconds(1)) {
    for (int i = 0; i < 1000; ++i) acc += decode_once(b, e);
    n += 1000;
  }
  const uint64_t iters = n * 2;

  uint64_t a0 = g_allocs;
  for (int i = 0; i < 1000; ++i) acc += decode_once(b, e);
  double allocs = double(g_allocs - a0) / 1000;

  std::vector<double> ns;
  for (int r = 0; r < 6; ++r) {
    auto s = clk::now();
    for (uint64_t i = 0; i < iters; ++i) acc += decode_once(b, e);
    double el = std::chrono::duration<double, std::nano>(clk::now() - s).count();
    ns.push_back(el / iters);
  }
  std::printf("%s\n  runs ns/packet:", label);
  for (double x : ns) std::printf(" %.1f", x);
  std::sort(ns.begin(), ns.end());
  std::printf("\n  median: %.1f ns/packet  (%llu packets/run, %.2f allocs/packet, checksum acc %lld)\n",
              (ns[2] + ns[3]) / 2, (unsigned long long)iters, allocs, (long long)acc);
}

int main(int argc, char **argv) {
  std::string dir = argc > 1 ? argv[1] : "../testdata";
  std::string xml = slurp(dir + "/templates.xml");
  std::string pkt = slurp(dir + "/increfresh.bin");
  std::printf("packet: %zu bytes; first-decode checksum must be %lld\n", pkt.size(), (long long)kWant);

  counting_allocator alloc;

  // (a) dynamic: runtime XML, generic interpreter decoder, by-name access.
  mfast::dynamic_templates_description desc(xml.c_str());
  mfast::fast_decoder dyn(&alloc);
  dyn.include({&desc});
  bench("mFAST dynamic (runtime XML, fast_decoder, by-name access)", pkt,
        [&](const char *b, const char *e) {
          return sum_dynamic(dyn.decode(b, e, /*force_reset=*/true));
        });

  // (b) static: fast_type_gen types, fast_decoder_v2 (decode code specialised
  // per template at compile time), generated accessors.
  mfast::fast_decoder_v2<0> st(&alloc, templates::description());
  bench("mFAST static (fast_type_gen, fast_decoder_v2, generated accessors)", pkt,
        [&](const char *b, const char *e) {
          return sum_static(st.decode(b, e, /*force_reset=*/true));
        });
  return 0;
}
